$ErrorActionPreference = 'Stop'
foreach ($m in @('workbuddy/hy4flash-free', 'auto/hy4flash-free')) {
    $body = @{
        model = $m
        messages = @(@{ role = 'user'; content = 'reply with OK only' })
        max_tokens = 16
    } | ConvertTo-Json -Depth 5
    $r = Invoke-RestMethod -Uri 'http://127.0.0.1:3425/v1/chat/completions' -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 60
    $content = $r.choices[0].message.content
    Write-Output ("{0} => {1}" -f $m, $content)
}

$ErrorActionPreference = 'Continue'
foreach ($m in @('workbuddy/hy4flash-free', 'auto/hy4flash-free')) {
    $body = @{
        model = $m
        messages = @(@{ role = 'user'; content = 'reply with OK only' })
        max_tokens = 16
    } | ConvertTo-Json -Depth 5
    try {
        $r = Invoke-RestMethod -Uri 'http://127.0.0.1:3425/v1/chat/completions' -Method Post -Body $body -ContentType 'application/json' -TimeoutSec 60
        Write-Output ("{0} => 200 => {1}" -f $m, $r.choices[0].message.content)
    } catch {
        $resp = $_.Exception.Response
        $code = if ($resp) { [int]$resp.StatusCode } else { 'no-http' }
        $detail = $_.ErrorDetails.Message
        if (-not $detail) { $detail = $_.Exception.Message }
        $short = ($detail -replace '\s+', ' ')
        if ($short.Length -gt 160) { $short = $short.Substring(0, 160) }
        Write-Output ("{0} => HTTP {1} => {2}" -f $m, $code, $short)
    }
}
